use crate::{Theme, ThemeError, Writer};
use std::path::PathBuf;

pub struct Kitty;

impl Writer for Kitty {
    fn name(&self) -> &'static str {
        "kitty"
    }

    fn output_path(&self) -> PathBuf {
        crate::home().join(".config/kitty/themes/active.conf")
    }

    fn enabled(&self) -> bool {
        crate::app_enabled("kitty", ".config/kitty")
    }

    fn generate(&self, theme: &Theme) -> Result<String, ThemeError> {
        let t = theme;
        Ok(format!(
            "# Generated by theme-manager. Do not edit manually.\n\
             # To use: add this line to ~/.config/kitty/kitty.conf:\n\
             #   include themes/active.conf\n\
             #\n\
             background_opacity {}\n\
             background {}\n\
             foreground {}\n\
             cursor {}\n\
             selection_background {}\n\
             selection_foreground {}\n\
\n\
             color0 {}\n\
             color1 {}\n\
             color2 {}\n\
             color3 {}\n\
             color4 {}\n\
             color5 {}\n\
             color6 {}\n\
             color7 {}\n\
             color8 {}\n\
             color9 {}\n\
             color10 {}\n\
             color11 {}\n\
             color12 {}\n\
             color13 {}\n\
             color14 {}\n\
             color15 {}\n",
            crate::get_transparency(t),
            t.require("BASE00")?,
            t.require("BASE05")?,
            t.require("BASE0D")?,
            t.require("BASE08")?,
            t.require("BASE0C")?,
            t.require("BASE00")?,
            t.require("BASE08")?,
            t.require("BASE0B")?,
            t.require("BASE0A")?,
            t.require("BASE0D")?,
            t.require("BASE0E")?,
            t.require("BASE0C")?,
            t.require("BASE07")?,
            t.require("BASE01")?,
            t.require("BASE08")?,
            t.require("BASE0B")?,
            t.require("BASE0A")?,
            t.require("BASE0D")?,
            t.require("BASE0E")?,
            t.require("BASE0C")?,
            t.require("BASE07")?,
        ))
    }
}
